function validate([paths]) {
  if (!Array.isArray(paths) || paths.length < 1 || paths.length > 20000) return 'paths needs 1 to 2 * 10^4 strings.';
  let total = 0;
  const dirs = new Set(), ancestors = new Set(), files = new Set();
  const shape = /^[A-Za-z0-9.]+(\/[A-Za-z0-9.]+)*( [A-Za-z0-9.]+\([A-Za-z0-9./]*\))+$/;
  for (const info of paths) {
    if (typeof info !== 'string' || info.length < 1 || info.length > 3000) return 'Each string has 1 to 3000 characters.';
    total += info.length;
    if (!shape.test(info)) return 'Each string is "dir/path name(content) name(content) ..." with single spaces.';
    const parts = info.split(' ');
    const dir = parts[0];
    if (dirs.has(dir)) return 'Each string must describe a different directory.';
    dirs.add(dir);
    const steps = dir.split('/');
    for (let k = 1; k <= steps.length; k++) ancestors.add(steps.slice(0, k).join('/'));
    for (let i = 1; i < parts.length; i++) {
      const full = dir + '/' + parts[i].slice(0, parts[i].indexOf('('));
      if (files.has(full)) return 'Two files in one directory cannot share a name.';
      files.add(full);
    }
  }
  if (total > 500000) return 'The strings hold at most 5 * 10^5 characters in total.';
  for (const full of files) if (ancestors.has(full)) return 'A file and a directory in one directory cannot share a name.';
  return null;
}

