function findDuplicate(paths) {
  const byContent = new Map();

  for (const info of paths) {
    const parts = info.split(' ');
    const directory = parts[0];
    for (let i = 1; i < parts.length; i++) {
      const open = parts[i].indexOf('(');
      const name = parts[i].slice(0, open);
      const content = parts[i].slice(open + 1, -1);
      if (!byContent.has(content)) {
        byContent.set(content, []);
      }
      byContent.get(content).push(directory + '/' + name);
    }
  }

  const groups = [];
  for (const files of byContent.values()) {
    if (files.length > 1) {
      groups.push(files);
    }
  }
  return groups;
}

