function findDuplicate(paths) {
  const files = [];
  for (const info of paths) {
    const match = info.match(/^(\S+) (.*)$/);
    const tokens = match[2].match(/[^ ()]+\([^)]*\)/g);
    for (const token of tokens) {
      const m = token.match(/^([^(]+)\((.*)\)$/);
      files.push({ path: match[1] + '/' + m[1], content: m[2] });
    }
  }
  const used = new Array(files.length).fill(false);
  const result = [];
  for (let i = 0; i < files.length; i++) {
    if (used[i]) continue;
    const group = [files[i].path];
    for (let j = i + 1; j < files.length; j++) {
      if (!used[j] && files[j].content === files[i].content) {
        used[j] = true;
        group.push(files[j].path);
      }
    }
    if (group.length >= 2) result.push(group);
  }
  return result;
}

