function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (alphabet, lo, hi) => {
    const len = int(lo, hi);
    let s = '';
    for (let i = 0; i < len; i++) s += alphabet[int(0, alphabet.length - 1)];
    return s;
  };
  const small = size === 'small';
  const dirCount = small ? int(1, 4) : 900;
  const pool = Array.from({ length: small ? int(1, 4) : 600 }, () => word('abcdefghijklmnopqrstuvwxyz0123456789', 1, small ? 4 : 12));
  const seen = new Set();
  const paths = [];
  while (paths.length < dirCount) {
    // Directory names have no '.', file names end in ".txt", so they never clash.
    const depth = int(0, small ? 2 : 5);
    let dir = 'root';
    for (let d = 0; d < depth; d++) dir += '/' + word(letters, 1, small ? 1 : 3);
    if (seen.has(dir)) continue;
    seen.add(dir);
    const fileCount = int(1, small ? 3 : 5);
    const names = new Set();
    while (names.size < fileCount) names.add(word(letters + '0123456789', 1, small ? 2 : 5) + '.txt');
    const files = [...names].map(name => `${name}(${pool[int(0, pool.length - 1)]})`);
    paths.push(dir + ' ' + files.join(' '));
  }
  return [paths];
}
